#' Estimate Phenological Divergence (Non-Overlap Area)
#'
#' Calculates the Non-Overlap Area (NOA) between two matrices of simulated
#' posterior probability density curves. Supports comparing two scenarios for
#' a single taxon or comparing two interacting taxa under a shared scenario.
#'
#' @param sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior density curves for the focal or shifted scenario, generated by [simulate_posterior_density()].
#' @param ref_sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior density curves for the reference scenario or second taxon, generated by [simulate_posterior_density()].
#' @return A list containing the posterior `Mean`, `Lower_CI` (2.5%), `Upper_CI` (97.5%), and `Posterior_Draws`.
#' @examples
#' data(sim_carabids)
#' mod <- mgcv::gam(
#'   Count ~ s(DOY, bs = "cc", k = 10) + ti(DOY, Latitude, bs = c("cc", "cr"), k = c(8, 4)) +
#'     s(Latitude, k = 4) + offset(LogEffort),
#'   family = poisson(), data = sim_carabids,
#'   knots = list(DOY = c(0.5, 365.5))
#' )
#' sim_south <- simulate_posterior_density(
#'   mod, create_newdata(mod, Latitude = "5%"), n_sims = 100, warnings = FALSE
#' )
#' sim_north <- simulate_posterior_density(
#'   mod, create_newdata(mod, Latitude = "95%"), n_sims = 100, warnings = FALSE
#' )
#' estimate_divergence(sim_south, sim_north)$Mean
#' @export
estimate_divergence <- function(sim_mat, ref_sim_mat) {
  grid_ref <- get_doy_grid(ref_sim_mat)
  grid_sim <- get_doy_grid(sim_mat)
  if (grid_sim$n_rows != grid_ref$n_rows) {
    stop("'sim_mat' and 'ref_sim_mat' must have the same number of temporal rows.")
  }

  n_draws <- min(ncol(sim_mat), ncol(ref_sim_mat))
  res <- 0.5 * colSums(abs(sim_mat[, seq_len(n_draws), drop = FALSE] -
                           ref_sim_mat[, seq_len(n_draws), drop = FALSE]))
  return(list(
    Mean = mean(res),
    Lower_CI = stats::quantile(res, 0.025),
    Upper_CI = stats::quantile(res, 0.975),
    Posterior_Draws = as.numeric(res)
  ))
}
